export const getQuerySparqlGetUrl = (params?: QuerySparqlGetParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/lod/sparql?${stringifiedParams}` : `/api/lod/sparql`
}

/**
 * Executes a SPARQL 1.1 query against an in-memory store loaded from the knowledge graph and ontology Turtle exports. SELECT/ASK results are returned as application/sparql-results+json, CONSTRUCT/DESCRIBE as Turtle. Updates are rejected. Without a query parameter, a short usage document is returned.
 * @summary Read-only SPARQL query endpoint
 */
